import "server-only";

import crypto from "node:crypto";
import { Prisma } from "@prisma/client";
import { headers } from "next/headers";
import { logServerError } from "@/lib/errors/server-error-log";
import { prisma } from "@/lib/prisma";
import type { AppSession } from "@/lib/auth/session";

function firstHeader(headersList: Headers, names: string[]) {
  for (const name of names) {
    const value = headersList.get(name);
    if (value) return value;
  }

  return null;
}

function getIp(headersList: Headers) {
  const forwarded = headersList.get("x-forwarded-for");
  if (forwarded) return forwarded.split(",")[0]?.trim() ?? null;

  return firstHeader(headersList, [
    "x-real-ip",
    "cf-connecting-ip",
    "x-client-ip",
  ]);
}

export async function getRequestAuditMetadata() {
  const headerStore = await headers();
  const ip = getIp(headerStore);

  return {
    ip,
    userAgent: headerStore.get("user-agent"),
    requestId:
      firstHeader(headerStore, ["x-request-id", "x-vercel-id", "cf-ray"]) ??
      undefined,
    geo: {
      country: headerStore.get("x-vercel-ip-country"),
      region: headerStore.get("x-vercel-ip-country-region"),
      city: headerStore.get("x-vercel-ip-city"),
      latitude: headerStore.get("x-vercel-ip-latitude"),
      longitude: headerStore.get("x-vercel-ip-longitude"),
      serviceProvider:
        headerStore.get("x-vercel-ip-asn") ??
        headerStore.get("cf-ipcountry") ??
        null,
    },
  };
}

export async function auditDeniedAccess(input: {
  session: AppSession;
  reason: string;
  required?: string[];
  entityType?: string;
  entityId?: string;
}) {
  if (!input.session.activeOrgId) return;

  try {
    const request = await getRequestAuditMetadata();

    await prisma.auditLog.create({
      data: {
        orgId: input.session.activeOrgId,
        actorUserId: input.session.userId,
        action: "ACCESS_DENIED",
        entityType: input.entityType ?? "Route",
        entityId: input.entityId ?? "unknown",
        ip: request.ip,
        userAgent: request.userAgent,
        requestId: request.requestId,
        metadata: {
          reason: input.reason,
          required: input.required ?? [],
          activeOrgRole: input.session.activeOrgRole,
          platformRole: input.session.platformRole,
          geo: request.geo,
        },
      },
    });
  } catch (error) {
    logServerError("audit.deniedAccess", error);
  }
}

export async function writeAuditLog(input: {
  orgId: string | null;
  actorUserId: string;
  action: string;
  entityType: string;
  entityId: string;
  metadata?: Prisma.InputJsonObject;
  beforeState?: Prisma.InputJsonObject | null;
  afterState?: Prisma.InputJsonObject | null;
}) {
  try {
    const request = await getRequestAuditMetadata();

    if (!input.orgId) {
      const auditId = `audit_${crypto.randomUUID().replace(/-/g, "")}`;
      await prisma.$executeRaw(
        Prisma.sql`
          insert into "AuditLog" (
            "id",
            "orgId",
            "actorUserId",
            "action",
            "entityType",
            "entityId",
            "metadata",
            "beforeState",
            "afterState",
            "ip",
            "userAgent",
            "requestId",
            "createdAt"
          )
          values (
            ${auditId},
            null,
            ${input.actorUserId},
            ${input.action},
            ${input.entityType},
            ${input.entityId},
            ${JSON.stringify({ ...(input.metadata ?? {}), geo: request.geo })}::jsonb,
            ${input.beforeState ? JSON.stringify(input.beforeState) : null}::jsonb,
            ${input.afterState ? JSON.stringify(input.afterState) : null}::jsonb,
            ${request.ip},
            ${request.userAgent},
            ${request.requestId},
            now()
          )
        `,
      );
      return;
    }

    await prisma.auditLog.create({
      data: {
        orgId: input.orgId,
        actorUserId: input.actorUserId,
        action: input.action,
        entityType: input.entityType,
        entityId: input.entityId,
        ip: request.ip,
        userAgent: request.userAgent,
        requestId: request.requestId,
        metadata: {
          ...(input.metadata ?? {}),
          geo: request.geo,
        },
        beforeState: input.beforeState ?? undefined,
        afterState: input.afterState ?? undefined,
      },
    });
  } catch (error) {
    logServerError("audit.write", error, {
      action: input.action,
      entityType: input.entityType,
      entityId: input.entityId,
    });
  }
}

export async function writePlatformAuditLog(input: {
  actorUserId: string;
  action: string;
  entityType: string;
  entityId: string;
  metadata?: Prisma.InputJsonObject;
  beforeState?: Prisma.InputJsonObject | null;
  afterState?: Prisma.InputJsonObject | null;
}) {
  return writeAuditLog({
    orgId: null,
    actorUserId: input.actorUserId,
    action: input.action,
    entityType: input.entityType,
    entityId: input.entityId,
    metadata: input.metadata,
    beforeState: input.beforeState,
    afterState: input.afterState,
  });
}
